qualities = {'public': True, 'staffed': True, 'well lit': False, 'busy at meeting time': True, 'easy to leave': False}
score = sum(1 for v in qualities.values() if v)
print('safe qualities:', score, 'of', len(qualities))
for k, v in qualities.items():
    print(k + ':', 'yes' if v else 'NO')
print('ground verdict:', 'meet as planned' if score == 5 else ('daylight only, tell someone' if score >= 3 else 'propose a safe alternative or abandon'))

steps = {'appearance matches listing': True, 'function tested': False, 'damage and wear examined': True, 'accessories counted': False, 'identifying marks noted': True}
score = sum(1 for v in steps.values() if v)
print('inspection steps done:', score, 'of', len(steps))
for k, v in steps.items():
    print(k + ':', 'done' if v else 'SKIPPED')
print('eyes-first verdict:', 'pay as agreed' if score == 5 else ('complete the missing steps first' if score == 4 else 'do not pay yet'))

proposals = {'platform payment': 'ACCEPT', 'bank transfer requested by seller': 'REFUSE', 'gift cards requested by seller': 'REFUSE and report', 'cash on collection with inspection': 'ACCEPT with inspection and receipt'}
for proposal, verdict in proposals.items():
    print(proposal + ' -> ' + verdict)
print('channel rule: inside the platform the record, the identity trail, and the dispute route all survive')

signals = {'sales spread over months': True, 'feedback from varied buyers': True, 'varied specific wording': False, 'problems handled openly': True}
score = sum(1 for v in signals.values() if v)
print('genuine shape signals:', score, 'of', len(signals))
for k, v in signals.items():
    print(k + ':', 'yes' if v else 'NO')
print('shape verdict:', 'proceed with normal checks' if score >= 3 else 'demand inspection and platform payment, or walk away')

shots = {'overall condition': True, 'wear and damage close-ups': True, 'identifying marks': True, 'included accessories': True, 'item with listing': True}
