for k, v in tests.items():
    print(k + ':', 'pass' if v else 'FAIL')
print('bench verdict:', 'pay as agreed' if score == 5 else 'renegotiate or walk away')

checks = {'markings match manufacturer info': False, 'materials and finish match': True, 'serial or code plausible': False, 'packaging and documents consistent': True, 'price gap explained': False}
